use reqwest::Client; use serde_json::{json,Value}; use thiserror::Error;
#[derive(Debug,Error)] pub enum WorkflowError { #[error("ollama: {0}")] Ollama(#[from] reqwest::Error), #[error("workflow failed: {0}")] Failed(String) }
async fn ask(c:&Client,base:&str,model:&str,system:&str,task:&str)->Result<String,WorkflowError>{ let u=format!("{}/api/chat",base.trim_end_matches('/')); let r=c.post(u).json(&json!({"model":model,"stream":false,"messages":[{"role":"system","content":system},{"role":"user","content":task}]})).send().await?; let v:Value=r.json().await?; Ok(v["message"]["content"].as_str().unwrap_or("").to_owned()) }
pub async fn run_simple(c:&Client,base:&str,model:&str,agent:&str,task:&str)->Result<Value,WorkflowError>{ let prompt=format!("You are the {} agent. Solve the task carefully. State assumptions and produce actionable output. Task: {}",agent,task); let answer=ask(c,base,model,"You are a reliable AI agent.",&prompt).await?; Ok(json!({"agent":agent,"status":"success","answer":answer})) }
pub async fn execute(c:&Client,base:&str,model:&str,workflow:&str,task:&str)->Result<Value,WorkflowError>{ match workflow { "research"=>{ let research=ask(c,base,model,"You are a research agent. Identify facts, uncertainties and sources to verify.",task).await?; let critique=ask(c,base,model,"You are a critical reviewer. Find unsupported claims and gaps in the following research.",&research).await?; let final_answer=ask(c,base,model,"You are a synthesizer. Produce a concise evidence-aware result using the research and critique.",&format!("RESEARCH:\n{}\nCRITIQUE:\n{}",research,critique)).await?; Ok(json!({"workflow":"research","research":research,"critique":critique,"result":final_answer})) }, _=>run_simple(c,base,model,workflow,task).await }
}
